#include <list>
#include <optional>
#include <unordered_map>
#include <mutex>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it == cache_.end()) {
            return std::nullopt;
        }
        // Move the accessed element to the front of the list (most recently used)
        usage_list_.splice(usage_list_.begin(), usage_list_, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            // Update existing key: move to front of the list
            it->second->second = value;
            usage_list_.splice(usage_list_.begin(), usage_list_, it->second);
            return;
        }
        // If at capacity, evict least recently used
        if (usage_list_.size() == capacity_) {
            auto lru_it = usage_list_.rbegin();
            cache_.erase(lru_it->first);
            usage_list_.erase(lru_it.base());
        }
        // Add new key to the front of the list
        usage_list_.emplace_front(key, value);
        cache_[key] = usage_list_.begin();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return cache_.size();
    }

private:
    std::size_t capacity_;
    std::list<std::pair<K, V>> usage_list_;
    std::unordered_map<K, std::list<std::pair<K, V>>::iterator> cache_;
    mutable std::mutex mutex_;
};
```

